B.acL=s(["Ranger tous les \xe9crans le matin","Prier ensemble, lire le Coran","Jouer \xe0 des jeux de soci\xe9t\xe9 ou dehors","Raconter comment on s'est senti le soir"],t.s)
B.Z5=new A.fx("Journ\xe9e sans \xe9crans","Passez une journ\xe9e sans t\xe9l\xe9phone ni tablette. Jouez, lisez, priez et riez ensemble.","\ud83d\udcf5","Une journ\xe9e","social",B.acL)
B.a7N=s(["Choisir la sourate (Al-Kawthar, Al-Asr...)","La lire ensemble chaque matin","Chacun apprend 1-2 versets par jour","La r\xe9citer ensemble vendredi"],t.s)
B.Z6=new A.fx("M\xe9moriser une sourate courte","Choisissez une sourate courte et apprenez-la ensemble pendant la semaine.","\ud83d\udd4b","Toute la semaine","apprentissage",B.a7N)
B.a3V=s(["Tirer au sort un nom","\xc9crire une lettre sinc\xe8re","Lire les lettres \xe0 voix haute","Faire une doua pour la famille"],t.s)
B.YX=new A.fx("Lettres de gratitude","Chaque membre \xe9crit une lettre de remerciement \xe0 un autre membre de la famille.","\u2709\ufe0f","30 min","social",B.a3V)
B.a6A=s(["Choisir Maghrib (id\xe9ale)","Faire les ablutions ensemble","Le papa dirige la pri\xe8re","Faire des douas ensemble apr\xe8s"],t.s)
B.Z1=new A.fx("Pri\xe8re en jama\xe2 \xe0 la maison","Organisez une pri\xe8re en groupe \xe0 la maison avec toute la famille.","\ud83d\udd4c","15 min","spirituel",B.a6A)
B.aco=s(["Choisir un Nom (Ar-Rahman, Al-Wadud...)","Chercher sa signification","Trouver des exemples dans la vie","L'utiliser dans les douas"],t.s)
B.Z2=new A.fx("D\xe9couvrir un Nom d'Allah","Choisissez un des 99 Noms d'Allah, apprenez sa signification et trouvez-le dans votre quotidien.","\u2728","Toute la semaine","apprentissage",B.aco)
B.ae0=s(["Pr\xe9parer gants et sacs","Aller dans un parc ou votre quartier","Ramasser les d\xe9chets ensemble","Rappeler le hadith sur le chemin propre"],t.s)
B.Z3=new A.fx("Ramasser des d\xe9chets dehors","Le Proph\xe8te \ufdfa a dit qu'enlever un obstacle du chemin est une sadaqa. Nettoyez un parc ensemble.","\ud83c\udf0d","1 heure","social",B.ae0)
