B.Lz=new A.dU("rawatib","Raw\xe2tib (Sunna r\xe9guli\xe8res)","Rawatib (Regular Sunnah)","\ud83d\udcff",15,"12 rak'at : 2 avant Fajr, 4 avant/2 apr\xe8s Dohr, 2 apr\xe8s Maghrib, 2 apr\xe8s Icha","12 rak'ahs: 2 before Fajr, 4 before/2 after Dohr, 2 after Maghrib, 2 after Isha")
