B.Ly=new A.dU("coran","Lecture du Coran","Quran Recitation","\ud83d\udcd6",15,null,null)
B.Ll=new A.dU("dhikr_matin","Adhk\xe2r du matin","Morning Adhkar","\ud83c\udf05",10,null,null)
