B.a6x=s(["Hagar","Mary","Sarah","Asiya"],t.s)
B.aoe=new A.b5("Qui \xe9tait la m\xe8re d'Ishaq ?","Who was the mother of Isaac?",B.a6y,B.a6x,2,"Sara, premi\xe8re femme d'Ibrahim, est la m\xe8re d'Ishaq, malgr\xe9 son \xe2ge avanc\xe9.","Sarah, the first wife of Abraham, is the mother of Isaac, despite her advanced age.",B.c6)
